result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/boulevard.js", "content": "import * as THREE from 'three';

const UP = new THREE.Vector3(0, 1, 0);
const ROAD_WIDTH = 6;
const POLE_HEIGHT = 5;

function toVector3(p) {
  if (p instanceof THREE.Vector3) return p.clone();
  return new THREE.Vector3(p[0], p[1], p[2]);
}

/** Horizontal normal of the curve at u: perpendicular to the tangent, lying flat. */
export function horizontalNormalAt(curve, u) {
  const tangent = curve.getTangentAt(u).normalize();
  return new THREE.Vector3().crossVectors(UP, tangent).normalize();
}

/**
 * Builds a winding boulevard: a Catmull-Rom road curve, a flattened road
 * strip mesh, and streetlamps alternating left/right along the road.
 */
export function buildBoulevard(points, { lights = 12, offset = 2.2 } = {}) {
  const controlPoints = points.map(toVector3);
  const curve = new THREE.CatmullRomCurve3(controlPoints, false);

  // --- flattened road strip mesh -------------------------------------------
  const segments = 128;
  const roadPositions = [];
  const roadIndices = [];
  for (let s = 0; s <= segments; s++) {
    const u = s / segments;
    const p = curve.getPointAt(u);
    const n = horizontalNormalAt(curve, u);
    roadPositions.push(
      p.x - n.x * ROAD_WIDTH / 2, p.y, p.z - n.z * ROAD_WIDTH / 2,
      p.x + n.x * ROAD_WIDTH / 2, p.y, p.z + n.z * ROAD_WIDTH / 2,
    );
    if (s < segments) {
      const a = s * 2;
      roadIndices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
  }
  const roadGeometry = new THREE.BufferGeometry();
  roadGeometry.setAttribute('position', new THREE.Float32BufferAttribute(roadPositions, 3));
  roadGeometry.setIndex(roadIndices);
  roadGeometry.computeVertexNormals();
  const road = new THREE.Mesh(
    roadGeometry,
    new THREE.MeshStandardMaterial({ color: 0x33363b, side: THREE.DoubleSide }),
  );

  // --- streetlamps ----------------------------------------------------------
  const lamps = [];
  for (let i = 0; i < lights; i++) {
    const u = lights > 1 ? i / (lights - 1) : 0;
    const point = curve.getPointAt(u);
    const n = horizontalNormalAt(curve, u);
    const side = i % 2 === 0 ? 1 : -1;

    const lamp = new THREE.Group();
    lamp.position.copy(point).addScaledVector(n, offset * side);

    // Orient the lamp so its local x axis faces the road.
    const xAxis = n.clone().multiplyScalar(-side);
    const zAxis = new THREE.Vector3().crossVectors(xAxis, UP);
    lamp.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(xAxis, UP.clone(), zAxis));

    const pole = new THREE.Mesh(
      new THREE.CylinderGeometry(0.07, 0.1, POLE_HEIGHT, 8),
      new THREE.MeshStandardMaterial({ color: 0x22252a }),
    );
    pole.position.y = POLE_HEIGHT / 2; // base sits at local y = 0
    lamp.add(pole);

    const head = new THREE.Mesh(
      new THREE.SphereGeometry(0.22, 12, 8),
      new THREE.MeshStandardMaterial({ color: 0xfff2cc, emissive: 0xffd9a0 }),
    );
    head.position.y = 3;
    lamp.add(head);

    const light = new THREE.PointLight(0xffd9a0, 30, 20, 2);
    light.position.y = 3;
    lamp.add(light);

    lamp.userData.side = side;
    lamp.userData.u = u;
    lamps.push(lamp);
  }

  return { curve, road, lamps };
}

/** Data about lamp i: world position, alternating side (+1/-1) and facing direction. */
export function lampData(b, i) {
  const lamp = b.lamps[i];
  const facing = new THREE.Vector3(1, 0, 0).applyQuaternion(lamp.quaternion);
  return {
    position: lamp.position.clone(),
    side: lamp.userData.side,
    facing,
  };
}
"})
