result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/boulevard.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildBoulevard, lampData } from '../src/boulevard.js';

const UP = new THREE.Vector3(0, 1, 0);

const WAYPOINTS = [
  [0, 0, 0],
  [10, 0, 4],
  [22, 0, -2],
  [34, 0, 6],
  [46, 0, 0],
  [58, 0, -4],
].map((p) => new THREE.Vector3(...p));

function horizontalNormalAt(curve, u) {
  const tangent = curve.getTangentAt(u).normalize();
  return new THREE.Vector3().crossVectors(UP, tangent).normalize();
}

describe('buildBoulevard', () => {
  const b = buildBoulevard(WAYPOINTS);

  it('uses a non-closed CatmullRomCurve3 over the six waypoints', () => {
    expect(b.curve).toBeInstanceOf(THREE.CatmullRomCurve3);
    expect(b.curve.closed).toBe(false);
    expect(b.curve.points).toHaveLength(6);
  });

  it('has a flattened road strip mesh', () => {
    expect(b.road).toBeInstanceOf(THREE.Mesh);
    const pos = b.road.geometry.getAttribute('position');
    expect(pos.count).toBeGreaterThan(2);
    for (let k = 0; k < pos.count; k++) expect(pos.getY(k)).toBeCloseTo(0, 12);
  });

  it('places 12 lamps that alternate sides strictly', () => {
    expect(b.lamps).toHaveLength(12);
    const sides = b.lamps.map((_, i) => lampData(b, i).side);
    for (const s of sides) expect(Math.abs(s)).toBe(1);
    for (let i = 1; i < sides.length; i++) {
      expect(sides[i]).toBe(-sides[i - 1]);
    }
  });

  it('keeps every lamp exactly `offset` from its curve point horizontally', () => {
    const offset = 2.2;
    b.lamps.forEach((_, i) => {
      const u = i / (b.lamps.length - 1);
      const cp = b.curve.getPointAt(u);
      const d = lampData(b, i).position;
      const dist = Math.hypot(d.x - cp.x, d.z - cp.z);
      expect(dist).toBeCloseTo(offset, 9);
    });
  });

  it('orients lamps so they face the road (facing · n = -side)', () => {
    b.lamps.forEach((_, i) => {
      const u = i / (b.lamps.length - 1);
      const n = horizontalNormalAt(b.curve, u);
      const { side, facing } = lampData(b, i);
      expect(facing.dot(n)).toBeCloseTo(-side, 6);
    });
  });

  it('rests every pole base at y = 0', () => {
    for (const lamp of b.lamps) {
      lamp.updateMatrixWorld(true);
      const pole = lamp.children.find((c) => c.isMesh && c.geometry.type === 'CylinderGeometry');
      expect(pole).toBeDefined();
      pole.geometry.computeBoundingBox();
      const base = pole.geometry.boundingBox.min.clone().applyMatrix4(pole.matrixWorld);
      expect(base.y).toBeCloseTo(0, 9);
    }
  });

  it('contains one PointLight per lamp', () => {
    let count = 0;
    for (const lamp of b.lamps) {
      lamp.traverse((o) => {
        if (o.isPointLight) count++;
      });
    }
    expect(count).toBe(12);
  });

  it('respects custom lights and offset options', () => {
    const b2 = buildBoulevard(WAYPOINTS, { lights: 7, offset: 3 });
    expect(b2.lamps).toHaveLength(7);
    let lights = 0;
    for (const lamp of b2.lamps) lamp.traverse((o) => o.isPointLight && lights++);
    expect(lights).toBe(7);
    b2.lamps.forEach((_, i) => {
      const u = i / 6;
      const cp = b2.curve.getPointAt(u);
      const d = lampData(b2, i).position;
      expect(Math.hypot(d.x - cp.x, d.z - cp.z)).toBeCloseTo(3, 9);
    });
  });
});
"})
